<?php require __DIR__.'/../includes/bootstrap.php';if(!empty($_SESSION['admin_id']))redirect(base_url('admin/index.php'));$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=db()->prepare('SELECT * FROM admins WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){$_SESSION['admin_id']=$u['id'];redirect(base_url('admin/index.php'));}$error='Invalid admin credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login | ECRS</title><link rel="stylesheet" href="<?=e(base_url('assets/css/styles.css'))?>"></head><body><div class="login-shell"><form class="login-card" method="post"><a class="public-brand" href="<?=e(base_url())?>"><span class="logo">▱</span><span><b style="font-size:24px">ECRS</b><small style="display:block;color:#627593">Administrator</small></span></a><h1 style="margin-top:28px">Admin Login</h1><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn primary w100">Login</button><p class="mini muted">Demo: admin@ecrs.local / Admin123!</p></form></div></body></html>